async function gs(d,t){if(!t)return null;try{const r=await d.prepare('SELECT u.id,u.username,u.role,u.display_name,s.expires_at FROM sessions s JOIN users u ON s.user_id=u.id WHERE s.token=?').bind(t).first();if(!r)return null;if(r.expires_at&&new Date(r.expires_at)<new Date()){await d.prepare('DELETE FROM sessions WHERE token=?').bind(t).run();return null;}return r;}catch(e){return null;}}
